function activeProduct(){return products.find(p=>p.use===state.use)||products[1]}
function productData(){return products.map(p=>({...p,...calc(state.lot,{...state,...p})}))}
function applyProduct(id){const p=products.find(p=>p.id===id);if(!p||!guardSelection())return;for(const k of ['floors','to','efficiency','unitArea','use'])state[k]=p[k];state.scenario='base';goExplore();notify(`${p.name}: hipótese aplicada. Ajuste as premissas no estúdio.`)}
function calc(lot=state.lot,config=state){
  const baseCa=2, maxCa=3, floors=config.floors;
  const legalFootprint=lot.area*config.to/100;
  const width=Math.max(0,lot.width-6),depth=Math.max(0,lot.depth-10);
  const setbackPlate=lot.custom?lot.area*.58:width*depth;
  const footprint=Math.max(0,Math.min(legalFootprint,setbackPlate,lot.area*maxCa/floors,config.use==='H1'?config.unitArea/(config.efficiency/100)/floors:Infinity));
  const gross=footprint*floors, sellable=gross*config.efficiency/100;
  const units=Math.floor((sellable+1e-7)/config.unitArea),saleArea=units*config.unitArea;
  const retail=config.use==='Misto'?footprint*.45:0;
  const residentialUnits=config.use==='Misto'?Math.max(0,Math.floor((sellable-retail)/config.unitArea)):units;
  const netSale=config.use==='Misto'?residentialUnits*config.unitArea+retail:saleArea;
  const totalBuilt=gross+(config.use==='H1'?0:lot.area*.35);
  const vgv=netSale*config.price,direct=totalBuilt*config.cost,indirect=direct*config.indirect/100;
  const nonLand=direct+indirect,targetProfit=vgv*config.profit/100,residual=vgv-nonLand-targetProfit;
  const margin=vgv>0?(vgv-nonLand-config.landPrice)/vgv*100:0;
  return {baseCa,maxCa,footprint,gross,sellable:netSale,units:residentialUnits,retail,totalBuilt,vgv,direct,indirect,nonLand,targetProfit,residual,margin,height:floors*3,ca:gross/lot.area,parking:Math.floor(lot.area*.35/28)};
}
