function focusMain(scroll=true){const h=$('main h1');if(h){h.tabIndex=-1;h.focus({preventScroll:true})}else $('#main-content').focus({preventScroll:true});if(scroll)$('#main-content').scrollTo({top:0,behavior:'instant'})}
function rememberControl(el){if(!el||!el.closest('#main-content'))return null;if(el.id)return '#'+CSS.escape(el.id);for(const key of ['action','product','use','layer','report','tab','scenario'])if(el.dataset[key])return `[data-${key}="${CSS.escape(el.dataset[key])}"]`;return null}
function trapFocus(e,root){if(e.key!=='Tab')return;const items=[...root.querySelectorAll('button:not(:disabled),a[href],input:not(:disabled),select,textarea,[tabindex="0"]')].filter(x=>x.getClientRects().length&&!x.closest('[inert]'));const first=items[0],last=items.at(-1);if(!first)return;if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}
function syncAccess(){const hasModal=!!$('.modal');$('#app').inert=hasModal;$('.main-shell').inert=menuOpen;$('#sidebar').inert=mobileQuery.matches&&!menuOpen;$('.prototype-switcher').inert=hasModal||menuOpen;$('#mobile-dock').inert=hasModal||menuOpen;$('.skip-link').inert=hasModal||menuOpen;$('#menu-backdrop').hidden=!menuOpen;$('#menu-backdrop').inert=hasModal;document.body.style.overflow=hasModal||menuOpen?'hidden':'';}
function syncMobileNavigation(){const current=state.page==='overview'?'overview':state.page==='projects'?'projects':state.page==='sources'?'sources':state.step===1?'find':state.step===2?'potential':state.tab;$$('[data-mobile-destination]').forEach(b=>{const active=b.dataset.mobileDestination===current;b.classList.toggle('is-active',active);if(active)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')});$('#glass-menu-context').textContent=state.lotConfirmed&&!state.lookupDirty?`${state.lot.name} · ${number(state.lot.area)} m² · estudo demonstrativo`:'Confirme o terreno para explorar o potencial.';$('#dock-menu').setAttribute('aria-expanded',menuOpen);$('#dock-menu').classList.toggle('is-active',menuOpen)}
function navigateMobile(destination){setMenu(false,false);if(['overview','projects','sources'].includes(destination)){state.page=destination;render();focusMain();return}state.page='analysis';if(destination==='find'){state.step=1;render();focusMain();return}if(!guardSelection()){focusMain();return}if(destination==='potential'){state.step=2;render();focusMain();return}goExplore(destination)}
function setMenu(open,restore=true){const next=Boolean(open&&mobileQuery.matches);if(next&&!menuOpen)menuReturnFocus=document.activeElement;menuOpen=next;$('#sidebar').classList.toggle('mobile-open',menuOpen);document.body.classList.toggle('glass-menu-open',menuOpen);$('#mobile-menu').setAttribute('aria-expanded',menuOpen);if(menuOpen){$('#sidebar').setAttribute('role','dialog');$('#sidebar').setAttribute('aria-modal','true');$('#sidebar').setAttribute('aria-labelledby','glass-menu-title')}else{for(const a of ['role','aria-modal','aria-label','aria-labelledby'])$('#sidebar').removeAttribute(a)}syncAccess();syncMobileNavigation();if(menuOpen){$('#sidebar').getBoundingClientRect();$('#drawer-close').focus({preventScroll:true})}else if(restore&&mobileQuery.matches){const target=menuReturnFocus?.isConnected&&menuReturnFocus.getClientRects().length?menuReturnFocus:$('#mobile-menu');target.focus({preventScroll:true})}}
mobileQuery.addEventListener('change',()=>{if(!mobileQuery.matches)setMenu(false,false);else syncAccess()});
function chooseLayout(){const descriptions={A:'Localize o lote e consulte o diagnóstico.',B:'Explore o volume com os controles ao lado.',C:'Veja o estudo em uma visão executiva.'};modal('Como você prefere explorar?',`<p>Três formas de ver o mesmo estudo. O terreno e as premissas são mantidos ao alternar.</p><div class="layout-choices">${Object.entries(variants).map(([key,label],i)=>`<button class="layout-choice ${state.variant===key?'active':''}" data-layout="${key}" aria-pressed="${state.variant===key}">${icon(['layers','cube','file'][i])}<span><strong>${label}</strong><small>${descriptions[key]}</small></span>${state.variant===key?status('ATUAL','confirmed'):''}</button>`).join('')}</div>`)}
document.addEventListener('click',e=>{const b=e.target.closest('[data-layout]');if(b){const v=b.dataset.layout;closeModal();setVariant(v);focusMain()}});
function modelDescription(){const c=calc();return `${state.floors} pavimentos · ${number(c.height)} m de altura · ${number(c.gross)} m² computáveis · ${activeProduct().name} · ${c.units} ${activeProduct().noun} de ${state.unitArea} m².`}
function updateRangeLabels(){for(const el of $$('input[data-control]'))el.setAttribute('aria-valuetext',el.dataset.control==='floors'?`${el.value} pavimentos`:el.dataset.control==='to'?`${el.value} por cento`:`${el.value} metros quadrados`)}
function announceResults(){clearTimeout(announceResults.timer);announceResults.timer=setTimeout(()=>$('#results-announcement').textContent=modelDescription(),450)}
function updateTableHints(){$$('.table-scroll').forEach(el=>{const hint=el.previousElementSibling;if(hint?.classList.contains('table-hint'))hint.hidden=el.scrollWidth<=el.clientWidth+1})}
function enhanceAccessibility(){
 $('#main-content').setAttribute('aria-busy','false');
 document.title=($('main h1')?.textContent||'Inteligência urbanística')+' | ViabilEasy';
 $$('.report-map [data-map-lot]').forEach(el=>{el.removeAttribute('data-map-lot');el.removeAttribute('role');el.removeAttribute('tabindex');el.removeAttribute('aria-label')});
 $$('.map-controls button,[data-action="layers"]').forEach(b=>b.disabled=!state.lotConfirmed);
 $('.report-map .map-svg')?.setAttribute('aria-label','Mapa esquemático do terreno selecionado para o relatório.');
 $$('#sidebar [data-page]').forEach(b=>{if(b.dataset.page===state.page)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');b.title=b.textContent.trim()});
 $$('[data-step]').forEach(b=>{const unavailable=Number(b.dataset.step)>1&&(!state.lotConfirmed||state.lookupDirty);b.disabled=unavailable;b.setAttribute('aria-disabled',unavailable);if(Number(b.dataset.step)===state.step)b.setAttribute('aria-current','step');else b.removeAttribute('aria-current')});
 $$('[data-action="analyze"]').forEach(b=>b.disabled=!state.lotConfirmed||state.lookupDirty);
 const mobileSelection=$('#map-selection');if(mobileSelection&&!state.lotConfirmed)mobileSelection.remove();
 $$('[data-use]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.use===state.use));updateRangeLabels();
 $$('table').forEach((table,i)=>{
  const title=table.closest('.panel')?.querySelector('h3')?.textContent||'Comparação de cenários';table.setAttribute('aria-label',title);
  table.querySelectorAll('thead th').forEach(th=>th.scope='col');
  if(table.classList.contains('compare-table')||table.classList.contains('sensitivity-table'))table.querySelectorAll('tbody tr').forEach(tr=>{const first=tr.firstElementChild;if(first.tagName==='TD'){const th=document.createElement('th');th.textContent=first.textContent;first.replaceWith(th)}tr.firstElementChild.scope='row'});
  if(!table.parentElement.classList.contains('table-scroll')){const holder=document.createElement('div');holder.className='table-scroll';holder.tabIndex=0;holder.setAttribute('role','region');holder.setAttribute('aria-label',title+'. Tabela com rolagem horizontal.');const hint=document.createElement('p');hint.className='table-hint';hint.id=`table-hint-${i}`;hint.textContent='Deslize a tabela ou use as setas com ela em foco para ver todas as colunas.';holder.setAttribute('aria-describedby',hint.id);table.before(hint,holder);holder.append(table);if(holder.parentElement.style.overflow==='auto')holder.parentElement.style.overflow='hidden';}
 });requestAnimationFrame(updateTableHints);
}
window.addEventListener('resize',updateTableHints);

document.addEventListener('paste',e=>{if(e.target.id!=='lookup-lat')return;const pair=parseCoordinatePair(e.clipboardData?.getData('text')||'');if(!pair)return;e.preventDefault();state.lookupValues.latitude=pair[0];state.lookupValues.longitude=pair[1];$('#lookup-lat').value=pair[0];$('#lookup-lng').value=pair[1];markLookupDirty();$('#results-announcement').textContent='Latitude e longitude preenchidas. Confira e localize o ponto.';});

render();
